import sys
from math import ceil

def main():
    import sys
    import heapq

    def read_ints():
        return list(map(int, sys.stdin.read().split()))

    data = read_ints()
    n = data[0]
    heights = data[1:]

    # Find all peaks
    peaks = []
    for i in range(1, n-1):
        if heights[i] > heights[i-1] and heights[i] > heights[i+1]:
            peaks.append(heights[i])

    # Add the first and last hills if they are peaks
    if n > 1 and heights[0] > heights[1]:
        peaks.append(heights[0])
    if n > 1 and heights[-1] > heights[-2]:
        peaks.append(heights[-1])

    # Sort peaks in descending order
    peaks.sort(reverse=True)

    # Calculate the minimum time required for each k
    result = []
    total_time = 0
    heap = []

    for k in range(1, ceil(n / 2) + 1):
        while len(heap) < k and len(peaks) > 0:
            heapq.heappush(heap, peaks.pop())

        if len(heap) < k:
            result.append(-1)
        else:
            total_time += sum(heap)
            result.append(total_time)

    print(" ".join(map(str, result)))

if __name__ == "__main__":
    main()
